// Semua contoh memakai C99 atau lebih baru. Kode hanya ditampilkan, tidak dijalankan di browser.
const multiple = (type, prompt, options, answer, explanation, code = '') => ({
  type, prompt, code, options: options.map((text, index) => ({ id: 'abcd'[index], text })), answer, explanation,
});
const choice = (prompt, options, answer, explanation, code) => multiple('choice', prompt, options, answer, explanation, code);
const bug = (prompt, code, options, answer, explanation) => multiple('bug', prompt, options, answer, explanation, code);
const output = (prompt, code, options, answer, explanation, expectedOutput) => ({
  ...multiple('output', prompt, options, answer, explanation, code), expectedOutput,
});
const logic = (prompt, code, options, answer, explanation, expectedOutput) => ({
  ...multiple('logic', prompt, options, answer, explanation, code),
  ...(expectedOutput === undefined ? {} : { expectedOutput }),
});
const fill = (prompt, code, accepted, explanation) => ({ type: 'fill', prompt, code, accepted, explanation });
const order = (prompt, lines, explanation) => ({
  type: 'order', prompt, tokens: lines.map((text, index) => ({ id: `line-${index + 1}`, text })),
  answer: lines.map((_, index) => `line-${index + 1}`), explanation,
});
const match = (prompt, pairs, explanation) => ({
  type: 'match', prompt, pairs: pairs.map(([left, right], index) => ({ id: `pair-${index + 1}`, left, right })), explanation,
});
const topic = (id, exercises) => exercises.map((exercise, index) => ({
  ...exercise, id: `${id}-${String(index + 1).padStart(2, '0')}`, ...(index === 9 ? { challenge: true } : {}),
}));

